// ═══ exceptionally — recovery on error ═══
CompletableFuture<String> result = CompletableFuture
    .supplyAsync(() -> {
        if (dbDown) throw new RuntimeException("DB connection failed!");
        return "SETTLED:TRD-001";
    })
    .exceptionally(ex -> {
        log.error("Settlement failed: {}", ex.getMessage());
        return "FAILED:TRD-001";  // recovery value!
    });
// Success: "SETTLED:TRD-001" (exceptionally NOT called)
// Failure: "FAILED:TRD-001" (exceptionally returns fallback)

// ═══ handle — always runs, transforms both cases ═══
CompletableFuture<String> status = CompletableFuture
    .supplyAsync(() -> settleTradeOrThrow("TRD-001"))
    .handle((result2, ex) -> {
        if (ex != null) {
            return "ERROR: " + ex.getMessage();  // error path
        }
        return "OK: " + result2;                  // success path
    });
// Always runs! Returns String either way.
// Like: try { return "OK:" + settle(); } catch (ex) { return "ERROR:" + ex; }

// ═══ whenComplete — side-effect only, no transform ═══
CompletableFuture<String> observed = CompletableFuture
    .supplyAsync(() -> settleTrade("TRD-001"))
    .whenComplete((result3, ex) -> {
        if (ex != null) log.error("Failed: {}", ex.getMessage());
        else log.info("Settled: {}", result3);
        // NO RETURN! Side-effect only!
        // Original result/exception passes through UNCHANGED!
    });
// Success: original "SETTLED:TRD-001" passes through
// Failure: original exception passes through (AND logging happened)

// ═══ COMPARISON ═══
// Method          Called when    Returns       Purpose
// exceptionally   error only     recovery T    recover from error
// handle          always         new U         transform both cases
// whenComplete    always         same T/error  observe (log/metrics)

// ═══ CHAINING MULTIPLE ═══
CompletableFuture.supplyAsync(() -> riskyOperation())
    .thenApply(result4 -> transform(result4))
    .exceptionally(ex -> fallbackValue())        // recovers
    .thenApply(value -> finalTransform(value))   // runs on recovered value too!
    .whenComplete((r, ex) -> log(r, ex));        // log final outcome
