// ─── File: src/test/java/com/bank/cfex/CFExceptionHandlingTest.java ───
package com.bank.cfex;

import org.junit.jupiter.api.Test;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import static org.assertj.core.api.Assertions.*;

class CFExceptionHandlingTest {

    // ═══ exceptionally — recovery on error ═══
    @Test
    void exceptionally_recoversOnError() throws Exception {
        CompletableFuture<String> cf = CompletableFuture
            .<String>supplyAsync(() -> { throw new RuntimeException("DB down!"); })
            .exceptionally(ex -> "FALLBACK: cached result");

        assertThat(cf.get()).isEqualTo("FALLBACK: cached result");
    }

    @Test
    void exceptionally_notCalledOnSuccess() throws Exception {
        CompletableFuture<String> cf = CompletableFuture
            .supplyAsync(() -> "SETTLED")
            .exceptionally(ex -> "FALLBACK");

        assertThat(cf.get()).isEqualTo("SETTLED");  // exceptionally NOT called!
    }

    // ═══ handle — always runs, transforms ═══
    @Test
    void handle_onSuccess() throws Exception {
        String result = CompletableFuture
            .supplyAsync(() -> "TRD-001")
            .handle((r, ex) -> ex != null ? "ERROR" : "OK:" + r)
            .get();

        assertThat(result).isEqualTo("OK:TRD-001");
    }

    @Test
    void handle_onFailure() throws Exception {
        String result = CompletableFuture
            .<String>supplyAsync(() -> { throw new RuntimeException("Failed!"); })
            .handle((r, ex) -> ex != null ? "ERROR:" + ex.getMessage() : "OK:" + r)
            .get();

        assertThat(result).isEqualTo("ERROR:Failed!");
    }

    // ═══ whenComplete — observe, no transform ═══
    @Test
    void whenComplete_observeSuccess() throws Exception {
        AtomicReference<String> logged = new AtomicReference<>();

        String result = CompletableFuture
            .supplyAsync(() -> "SETTLED")
            .whenComplete((r, ex) -> logged.set(ex != null ? "FAIL" : "OK:" + r))
            .get();

        assertThat(result).isEqualTo("SETTLED");  // ORIGINAL result passes through!
        assertThat(logged.get()).isEqualTo("OK:SETTLED");  // side-effect logged!
    }

    @Test
    void whenComplete_observeFailure() {
        AtomicReference<String> logged = new AtomicReference<>();

        CompletableFuture<String> cf = CompletableFuture
            .<String>supplyAsync(() -> { throw new RuntimeException("DB down!"); })
            .whenComplete((r, ex) -> logged.set(ex != null ? "FAIL:" + ex.getMessage() : "OK"));

        assertThatThrownBy(cf::join).isInstanceOf(CompletionException.class);
        assertThat(logged.get()).isEqualTo("FAIL:DB down!");  // logged but error passes through!
    }

    // ═══ Full pipeline with all three ═══
    @Test
    void fullPipeline() throws Exception {
        AtomicReference<String> metric = new AtomicReference<>();

        String result = CompletableFuture
            .supplyAsync(() -> "100000")
            .thenApply(Integer::parseInt)
            .thenApply(bal -> bal > 50000 ? "ELIGIBLE" : "INELIGIBLE")
            .exceptionally(ex -> "ERROR")
            .whenComplete((r, ex) -> metric.set("outcome=" + r))
            .get();

        assertThat(result).isEqualTo("ELIGIBLE");
        assertThat(metric.get()).isEqualTo("outcome=ELIGIBLE");
    }
}
